@@ -1,7 +1,17 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+export interface CommitSignature {
+  isSigned: boolean;
+  isValid?: boolean;
+}
+
+export const provenanceOf = (signature: CommitSignature): Provenance => {
+  // Provenance is determined by cryptographic evidence only. Git author/committer
+  // fields and commit message trailers are self-asserted and can be forged with
+  // `git commit --author=...` or by editing commit bodies. Only trust signatures
+  // that git has verified against locally-available keys (no network, no key mgmt).
+  if (signature.isSigned && signature.isValid === true) {
+    return "authored";
+  }
   return "unknown";
 };
